  1→{% comment %}
  2→  Zip Code Checker — Theme App Extension Block
  3→  Add this block to any section in the Shopify Theme Editor.
  4→  The block automatically connects to your app — no manual configuration needed.
  5→{% endcomment %}
  6→
  7→{% assign zcc_config = app.metafields.zip_checker.widget_config.value %}
  8→
  9→<div
 10→  id="zcc-widget-{{ block.id }}"
 11→  data-shop="{{ shop.permanent_domain }}"
 12→  data-api="https://{{ shop.permanent_domain }}/apps/zipcheck"
 13→  data-block="{{ block.id }}"
 14→  {% if zcc_config %}data-config="{{ zcc_config | json | escape }}"{% endif %}
 15→  {{ block.shopify_attributes }}
 16→></div>
 17→
 18→<script>
 19→(function () {
 20→  var ROOT_ID = "zcc-widget-{{ block.id }}";
 21→  var container = document.getElementById(ROOT_ID);
 22→  if (!container) return;
 23→
 24→  var SHOP = container.dataset.shop;
 25→  var API_BASE = (container.dataset.api || "").replace(/\/$/, "");
 26→
 27→  // Try embedded config from metafield first (instant, no network needed)
 28→  var configStr = container.getAttribute("data-config");
 29→  if (configStr) {
 30→    try {
 31→      renderWidget(JSON.parse(configStr));
 32→      return;
 33→    } catch (e) {
 34→      console.warn("[ZipCodeChecker] Failed to parse embedded config, falling back to API");
 35→    }
 36→  }
 37→
 38→  // Fallback: fetch config from API
 39→  fetch(API_BASE + "/api/widget-config?shop=" + encodeURIComponent(SHOP))
 40→    .then(function (r) {
 41→      if (!r.ok) throw new Error("Widget config API returned " + r.status);
 42→      return r.json();
 43→    })
 44→    .then(function (cfg) { renderWidget(cfg); })
 45→    .catch(function (err) {
 46→      console.warn("[ZipCodeChecker] Could not load widget config, using defaults:", err.message || err);
 47→      renderWidget({});
 48→    });
 49→
 50→  function renderWidget(cfg) {
 51→    // Merge with defaults
 52→    var D = {
 53→      position: "inline",
 54→      heading: "Check Delivery Availability",
 55→      placeholder: "Enter your zip code",
 56→      buttonText: "Check",
 57→      successMessage: "Great news! We deliver to your area.",
 58→      errorMessage: "Sorry, we don\u2019t deliver to this area yet.",
 59→      notFoundMessage: "This zip code was not found in our system.",
 60→      primaryColor: "#008060",
 61→      successColor: "#008060",
 62→      errorColor: "#D72C0D",
 63→      backgroundColor: "#FFFFFF",
 64→      textColor: "#202223",
 65→      borderRadius: "8",
 66→      showEta: true,
 67→      showZone: false,
 68→      showWaitlistOnFailure: false,
 69→      customCss: "",
 70→    };
 71→    Object.keys(D).forEach(function (k) {
 72→      if (cfg[k] === undefined || cfg[k] === null || cfg[k] === "") cfg[k] = D[k];
 73→    });
 74→
 75→    var rad = cfg.borderRadius + "px";
 76→    var WID = "zcc-" + ROOT_ID;
 77→
 78→    if (cfg.position === "floating") {
 79→      renderFloating(cfg, WID, rad);
 80→    } else if (cfg.position === "popup") {
 81→      renderPopup(cfg, WID, rad);
 82→    } else {
 83→      renderInline(cfg, WID, rad);
 84→    }
 85→  }
 86→
 87→  // ── Shared: inject CSS ──────────────────────────────────────────────────────
 88→  function injectCss(wid, cfg, rad) {
 89→    var css =
 90→      "#" + wid + "{" +
 91→        "background:" + cfg.backgroundColor + " !important;" +
 92→        "color:" + cfg.textColor + " !important;" +
 93→        "border-radius:" + rad + " !important;" +
 94→        "padding:24px !important;" +
 95→        "border:1px solid #e1e3e5 !important;" +
 96→        "max-width:480px;" +
 97→        "font-family:-apple-system,BlinkMacSystemFont,'Segoe UI',Roboto,sans-serif !important;" +
 98→        "box-sizing:border-box !important;" +
 99→      "}" +
100→      "#" + wid + " *{box-sizing:border-box !important}" +
101→      "#" + wid + " .zcc-heading{font-size:16px !important;font-weight:600 !important;margin:0 0 16px !important;color:" + cfg.textColor + " !important}" +
102→      "#" + wid + " .zcc-row{display:flex !important;gap:8px !important;margin-bottom:0 !important}" +
103→      "#" + wid + " .zcc-input{" +
104→        "flex:1 !important;padding:10px 12px !important;border:1px solid #c9cccf !important;" +
105→        "border-radius:" + rad + " !important;font-size:14px !important;outline:none !important;" +
106→        "background:#fafbfb !important;color:" + cfg.textColor + " !important;min-width:0 !important" +
107→      "}" +
108→      "#" + wid + " .zcc-input:focus{border-color:" + cfg.primaryColor + " !important;box-shadow:0 0 0 2px " + cfg.primaryColor + "22 !important}" +
109→      "#" + wid + " .zcc-btn{" +
110→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
111→        "border-radius:" + rad + " !important;padding:10px 20px !important;font-size:14px !important;" +
112→        "font-weight:600 !important;cursor:pointer !important;white-space:nowrap !important;flex-shrink:0 !important" +
113→      "}" +
114→      "#" + wid + " .zcc-btn:hover{opacity:.9 !important}" +
115→      "#" + wid + " .zcc-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
116→      "#" + wid + " .zcc-result{margin-top:12px !important;padding:12px !important;border-radius:" + rad + " !important;font-size:14px !important;line-height:1.4 !important}" +
117→      "#" + wid + " .zcc-result.ok{background:" + cfg.successColor + "15 !important;border-left:3px solid " + cfg.successColor + " !important;color:" + cfg.successColor + " !important}" +
118→      "#" + wid + " .zcc-result.fail{background:" + cfg.errorColor + "15 !important;border-left:3px solid " + cfg.errorColor + " !important;color:" + cfg.errorColor + " !important}" +
119→      "#" + wid + " .zcc-meta{margin-top:4px !important;font-size:13px !important;opacity:.8 !important}" +
120→      "#" + wid + " .zcc-wl{margin-top:10px !important}" +
121→      "#" + wid + " .zcc-wl-input{" +
122→        "width:100% !important;padding:8px 10px !important;border:1px solid " + cfg.errorColor + "40 !important;" +
123→        "border-radius:" + rad + " !important;font-size:13px !important;margin-bottom:6px !important;display:block !important" +
124→      "}" +
125→      "#" + wid + " .zcc-wl-btn{" +
126→        "background:" + cfg.errorColor + " !important;color:#fff !important;border:none !important;" +
127→        "border-radius:" + rad + " !important;padding:8px 16px !important;font-size:13px !important;" +
128→        "cursor:pointer !important;width:100% !important;font-weight:600 !important" +
129→      "}" +
130→      "#" + wid + " .zcc-wl-btn:disabled{opacity:.6 !important;cursor:not-allowed !important}" +
131→      (cfg.customCss || "");
132→
133→    var styleEl = document.createElement("style");
134→    styleEl.textContent = css;
135→    document.head.appendChild(styleEl);
136→  }
137→
138→  // ── Shared: build widget inner HTML + wire up events ────────────────────────
139→  function buildWidgetInner(wid, cfg, btnLabel) {
140→    return (
141→      '<p class="zcc-heading">' + esc(cfg.heading) + "</p>" +
142→      '<div class="zcc-row">' +
143→        '<input class="zcc-input" type="text" id="' + wid + '-inp"' +
144→          ' placeholder="' + escAttr(cfg.placeholder) + '"' +
145→          ' aria-label="' + escAttr(cfg.placeholder) + '" />' +
146→        '<button class="zcc-btn" id="' + wid + '-btn" type="button">' + esc(btnLabel) + "</button>" +
147→      "</div>" +
148→      '<div id="' + wid + '-res"></div>'
149→    );
150→  }
151→
152→  function wireWidget(wid, cfg, API_BASE, SHOP) {
153→    var inp = document.getElementById(wid + "-inp");
154→    var btn = document.getElementById(wid + "-btn");
155→    var res = document.getElementById(wid + "-res");
156→    var btnLabel = cfg.buttonText;
157→    if (!inp || !btn || !res) return;
158→
159→    function checkZip() {
160→      var zip = inp.value.trim();
161→      if (!zip) { inp.focus(); return; }
162→
163→      btn.disabled = true;
164→      btn.textContent = "\u2026";
165→      res.innerHTML = "";
166→
167→      fetch(
168→        API_BASE + "/api/zip-check?shop=" + encodeURIComponent(SHOP) +
169→          "&zip=" + encodeURIComponent(zip)
170→      )
171→        .then(function (r) { return r.json(); })
172→        .then(function (data) {
173→          btn.disabled = false;
174→          btn.textContent = btnLabel;
175→
176→          if (data.allowed) {
177→            var html = '<div class="zcc-result ok">' + esc(data.message);
178→            if (cfg.showEta && data.eta) {
179→              html += '<div class="zcc-meta">Estimated delivery: ' + esc(data.eta) + "</div>";
180→            }
181→            if (cfg.showZone && data.zone) {
182→              html += '<div class="zcc-meta">Zone: ' + esc(data.zone) + "</div>";
183→            }
184→            html += "</div>";
185→            res.innerHTML = html;
186→          } else {
187→            var html = '<div class="zcc-result fail">' + esc(data.message);
188→            if (cfg.showWaitlistOnFailure) {
189→              html +=
190→                '<div class="zcc-wl">' +
191→                '<input class="zcc-wl-input" type="email" id="' + wid + '-wl-email" placeholder="Enter email to join waitlist" />' +
192→                '<button class="zcc-wl-btn" id="' + wid + '-wl-btn" type="button">Join Waitlist</button>' +
193→                "</div>";
194→            }
195→            html += "</div>";
196→            res.innerHTML = html;
197→
198→            if (cfg.showWaitlistOnFailure) {
199→              var wBtn = document.getElementById(wid + "-wl-btn");
200→              if (wBtn) {
201→                wBtn.addEventListener("click", function () {
202→                  var emailEl = document.getElementById(wid + "-wl-email");
203→                  var email = emailEl ? emailEl.value.trim() : "";
204→                  if (!email) { if (emailEl) emailEl.focus(); return; }
205→                  joinWaitlist(zip, email, wBtn);
206→                });
207→              }
208→            }
209→          }
210→        })
211→        .catch(function () {
212→          btn.disabled = false;
213→          btn.textContent = btnLabel;
214→          res.innerHTML = '<div class="zcc-result fail">Something went wrong. Please try again.</div>';
215→        });
216→    }
217→
218→    btn.addEventListener("click", checkZip);
219→    inp.addEventListener("keydown", function (e) {
220→      if (e.key === "Enter") checkZip();
221→    });
222→  }
223→
224→  function joinWaitlist(zip, email, wBtn) {
225→    wBtn.disabled = true;
226→    wBtn.textContent = "Joining\u2026";
227→
228→    fetch(API_BASE + "/api/waitlist", {
229→      method: "POST",
230→      headers: { "Content-Type": "application/json" },
231→      body: JSON.stringify({ shop: SHOP, zip: zip, email: email }),
232→    })
233→      .then(function (r) { return r.json(); })
234→      .then(function (data) {
235→        var wlEl = wBtn.closest(".zcc-wl");
236→        if (data.success) {
237→          if (wlEl) wlEl.innerHTML =
238→            '<p style="font-size:13px;margin:6px 0 0">' +
239→            "\u2713 You\u2019ve been added to the waitlist!" +
240→            "</p>";
241→        } else {
242→          wBtn.disabled = false;
243→          wBtn.textContent = "Join Waitlist";
244→        }
245→      })
246→      .catch(function () {
247→        wBtn.disabled = false;
248→        wBtn.textContent = "Join Waitlist";
249→      });
250→  }
251→
252→  // ── Inline position ─────────────────────────────────────────────────────────
253→  function renderInline(cfg, WID, rad) {
254→    injectCss(WID, cfg, rad);
255→    container.id = WID;
256→    container.innerHTML = buildWidgetInner(WID, cfg, cfg.buttonText);
257→    wireWidget(WID, cfg, API_BASE, SHOP);
258→  }
259→
260→  // ── Floating position ────────────────────────────────────────────────────────
261→  function renderFloating(cfg, WID, rad) {
262→    // The original container becomes invisible (just an anchor)
263→    container.style.display = "none";
264→
265→    injectCss(WID, cfg, rad);
266→
267→    // Additional styles for floating UI
268→    var floatCss =
269→      "#" + WID + "-float{position:fixed !important;bottom:20px !important;right:20px !important;z-index:9998 !important;display:flex !important;flex-direction:column !important;align-items:flex-end !important;gap:10px !important}" +
270→      "#" + WID + "-panel{" +
271→        "background:" + cfg.backgroundColor + " !important;border-radius:" + rad + " !important;" +
272→        "box-shadow:0 8px 32px rgba(0,0,0,.18) !important;overflow:hidden !important;" +
273→        "transition:opacity .2s,transform .2s;transform-origin:bottom right" +
274→      "}" +
275→      "#" + WID + "-panel.zcc-hidden{display:none !important}" +
276→      "#" + WID + "-panel .zcc-panel-header{" +
277→        "display:flex !important;align-items:center !important;justify-content:space-between !important;" +
278→        "padding:14px 16px 0 !important;margin-bottom:0 !important" +
279→      "}" +
280→      "#" + WID + "-panel .zcc-panel-close{" +
281→        "background:none !important;border:none !important;cursor:pointer !important;font-size:20px !important;line-height:1 !important;" +
282→        "color:" + cfg.textColor + " !important;opacity:.6;padding:0 4px !important" +
283→      "}" +
284→      "#" + WID + "-panel .zcc-panel-close:hover{opacity:1 !important}" +
285→      "#" + WID + "-trigger{" +
286→        "background:" + cfg.primaryColor + " !important;color:#fff !important;border:none !important;" +
287→        "border-radius:50px !important;padding:12px 20px !important;font-size:14px !important;font-weight:600 !important;" +
288→        "cursor:pointer !important;box-shadow:0 4px 12px rgba(0,0,0,.2) !important;white-space:nowrap !important" +
289→      "}" +
290→      "#" + WID + "-trigger:hover{opacity:.9 !important}";
291→
292→    var floatStyle = document.createElement("style");
293→    floatStyle.textContent = floatCss;
294→    document.head.appendChild(floatStyle);
295→
296→    // Build floating shell
297→    var floatEl = document.createElement("div");
298→    floatEl.id = WID + "-float";
299→    floatEl.innerHTML =
300→      '<div id="' + WID + '-panel" class="zcc-hidden">' +
301→        '<div class="zcc-panel-header">' +
302→          '<span style="font-size:13px;font-weight:600;color:' + cfg.textColor + '">Delivery Check</span>' +
303→          '<button class="zcc-panel-close" id="' + WID + '-close" type="button" aria-label="Close">&times;</button>' +
304→        '</div>' +
305→        '<div id="' + WID + '">' +
306→          buildWidgetInner(WID, cfg, cfg.buttonText) +
307→        '</div>' +
308→      '</div>' +
309→      '<button id="' + WID + '-trigger" type="button">' +
310→        '<svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.5" style="vertical-align:middle;margin-right:6px"><path d="M21 10c0 7-9 13-9 13s-9-6-9-13a9 9 0 0118 0z"/><circle cx="12" cy="10" r="3"/></svg>' +
311→        esc(cfg.buttonText || "Check Delivery") +
312→      '</button>';
313→
314→    document.body.appendChild(floatEl);
315→
316→    // Wire toggle
317→    var trigger = document.getElementById(WID + "-trigger");
318→    var panel = document.getElementById(WID + "-panel");
319→    var closeBtn = document.getElementById(WID + "-close");
320→
321→    if (trigger && panel) {
322→      trigger.addEventListener("click", function () {
323→        panel.classList.toggle("zcc-hidden");
324→      });
325→    }
326→    if (closeBtn && panel) {
327→      closeBtn.addEventListener("click", function () {
328→        panel.classList.add("zcc-hidden");
329→      });
330→    }
331→    // Close on outside click
332→    document.addEventListener("click", function (e) {
333→      if (!floatEl.contains(e.target)) {
334→        if (panel) panel.classList.add("zcc-hidden");
335→      }
336→    });
337→
338→    wireWidget(WID, cfg, API_BASE, SHOP);
339→  }
340→
341→  // ── Popup position ───────────────────────────────────────────────────────────
342→  function renderPopup(cfg, WID, rad) {
343→    injectCss(WID, cfg, rad);
344→
345→    var popupCss =
346→      "#" + WID + "-overlay{" +
347→        "display:none !important;position:fixed !important;inset:0 !important;background:rgba(0,0,0,.55) !important;" +
348→        "z-index:9999 !important;align-items:center !important;justify-content:center !important;padding:16px !important" +
349→      "}" +
350→      "#" + WID + "-overlay.zcc-open{display:flex !important}" +
351→      "#" + WID + "-modal{" +
352→        "background:" + cfg.backgroundColor + " !important;border-radius:" + rad + " !important;" +
353→        "max-width:480px !important;width:100% !important;position:relative !important;" +
354→        "box-shadow:0 20px 60px rgba(0,0,0,.3) !important" +
355→      "}" +
